import React from 'react';
import { ToastProvider } from './components/Toast';
import { BrowserRouter, Routes, Route, Navigate, useLocation } from 'react-router-dom';
import { QueryClient, QueryClientProvider, useQuery } from '@tanstack/react-query';
import { AuthProvider, useAuth } from './context/AuthContext';
import { API_BASE } from './lib/apiConfig';
import Layout from './components/Layout';
import Login from './pages/Login';
import ForgotPassword from './pages/ForgotPassword';
import ResetPassword from './pages/ResetPassword';
import Dashboard from './pages/Dashboard';
import Users from './pages/Users';
import Events from './pages/Events';
import Clubs from './pages/Clubs';
import Ticketing from './pages/Ticketing';
import Admins from './pages/Admins';
import Analytics from './pages/Analytics';
import AdsBroadcast from './pages/AdsBroadcast';
import PollsContests from './pages/PollsContests';
import SupportActivity from './pages/SupportActivity';
import ContactSupport from './pages/ContactSupport';
import ActivityLogs from './pages/ActivityLogs';
import Settings from './pages/Settings';
import ManageFilters from './pages/ManageFilters';

const queryClient = new QueryClient({
  defaultOptions: {
    queries: {
      refetchOnWindowFocus: false,
      retry: 1,
    },
  },
});

import ClubOnboarding from './pages/ClubOnboarding';
import EventAdminOnboarding from './pages/EventAdminOnboarding';
import OrganiserRequests from './pages/OrganiserRequests';
import PendingApproval from './pages/PendingApproval';
import Bookings from './pages/Bookings';
import Signup from './pages/Signup';

const ProtectedRoute = ({
  children,
  requireSuperAdmin = false,
  allowedRoles
}: {
  children: React.ReactNode,
  requireSuperAdmin?: boolean,
  allowedRoles?: string[]
}) => {
  const { user, token, isLoading } = useAuth();
  // BUG FIX: every check below used to compare window.location.pathname
  // directly against bare route strings like '/club-onboarding'. That's
  // the *browser's* pathname, which includes the router's basename
  // ("/app/admin") — so window.location.pathname is always something
  // like "/app/admin/club-onboarding", never the bare "/club-onboarding"
  // these checks expected. Every one of them was permanently false (or
  // permanently true, for the "!==" ones), which meant a fresh
  // CLUB_ADMIN/EVENT_ADMIN account (no organisation yet) landing on its
  // own onboarding page immediately got redirected... back to the exact
  // same onboarding page, forever — an infinite loop that silently
  // never renders anything (no error, since Navigate doesn't throw) and
  // leaves a permanently blank screen. useLocation() returns the path
  // *relative to the basename*, which is what actually matches the
  // route definitions below.
  const location = useLocation();
  const pathname = location.pathname;

  // Was previously missing entirely — the only gate was `!user.organisation`,
  // which becomes true the instant the registration form is submitted,
  // regardless of whether the Vendor record behind it has actually been
  // approved. A brand-new, unapproved club got identical access to an
  // approved one. This checks the real backend verification status.
  // FIXED: this whole approval gate previously only ever checked
  // CLUB_ADMIN — EVENT_ADMIN had no equivalent check at all, meaning an
  // Event Admin got full dashboard access the instant `organisation` was
  // set locally, with zero backend verification. Generalized to cover
  // both roles the same way.
  const { data: ownVendorStatus, isLoading: vendorCheckLoading } = useQuery({
    queryKey: ['own-vendor-status'],
    queryFn: async () => {
      const res = await fetch(`${API_BASE}/vendor/my-status`, {
        headers: { Authorization: `Bearer ${token}` },
      });
      const json = await res.json();
      return json.data ?? null;
    },
    enabled: (user?.role === 'CLUB_ADMIN' || user?.role === 'EVENT_ADMIN') && Boolean(token),
  });

  if (isLoading) return <div className="min-h-screen flex items-center justify-center bg-[#0B0B0F] text-white font-bold uppercase tracking-widest text-xs">Loading...</div>;
  if (!user) return <Navigate to="/login" replace />;
  if (requireSuperAdmin && user.role !== 'SUPER_ADMIN') return <Navigate to="/" replace />;

  // Onboarding check for CLUB_ADMIN
  const isClaiming = pathname.startsWith('/claim-club/') || pathname.startsWith('/claim-organiser/');
  if (user.role === 'CLUB_ADMIN' && !user.organisation && pathname !== '/club-onboarding' && !isClaiming) {
    return <Navigate to="/club-onboarding" replace />;
  }

  // Onboarding check for EVENT_ADMIN
  if (user.role === 'EVENT_ADMIN' && !user.organisation && pathname !== '/event-onboarding') {
    return <Navigate to="/event-onboarding" replace />;
  }

  // Approval gate for CLUB_ADMIN and EVENT_ADMIN — organisation is set,
  // but the vendor behind it isn't verified yet. Don't gate the
  // onboarding/claim pages themselves, the pending-approval page, or the
  // admin's own profile page (they land there straight after onboarding
  // now, with a "pending verification" badge/banner instead of a
  // separate blank holding page), to avoid a redirect loop / dead end.
  const isPendingApprovalPage = pathname === '/pending-approval';
  const isOwnOnboardingPage =
    (user.role === 'CLUB_ADMIN' && pathname === '/club-onboarding') ||
    (user.role === 'EVENT_ADMIN' && pathname === '/event-onboarding');
  const isOwnProfilePage =
    (user.role === 'CLUB_ADMIN' && pathname === '/club-profile') ||
    (user.role === 'EVENT_ADMIN' && pathname === '/event-profile');
  if (
    (user.role === 'CLUB_ADMIN' || user.role === 'EVENT_ADMIN') &&
    user.organisation &&
    !isClaiming &&
    !isOwnOnboardingPage &&
    !isPendingApprovalPage &&
    !isOwnProfilePage
  ) {
    if (vendorCheckLoading) {
      return <div className="min-h-screen flex items-center justify-center bg-[#0B0B0F] text-white font-bold uppercase tracking-widest text-xs">Loading...</div>;
    }
    if (!ownVendorStatus?.is_verified) {
      return <Navigate to="/pending-approval" replace />;
    }
  }

  if (allowedRoles && !allowedRoles.includes(user.role)) return <Navigate to="/" replace />;

  return <>{children}</>;
};

import AccountSettings from './pages/AccountSettings';
import EventAccountSettings from './pages/EventAccountSettings';
import ClaimClubForm from './pages/ClaimClubForm';
import ClaimOrganiserForm from './pages/ClaimOrganiserForm';
import EventAdminProfilePage from './pages/EventAdminProfilePage';
import ClubProfilePage from './pages/ClubProfilePage';
import ComingSoon from './pages/ComingSoon';

export default function App() {
  return (
    <QueryClientProvider client={queryClient}>
        <ToastProvider>
      <AuthProvider>
        <BrowserRouter basename="/app/admin">
          <Routes>
            <Route path="/login" element={<Login />} />
            <Route path="/signup" element={<Signup />} />
            <Route path="/forgot-password" element={<ForgotPassword />} />
            {/* Matches the link emailed by POST /auth/forget_password:
                https://hii.life/app/admin/reset-password/:token */}
            <Route path="/reset-password/:token" element={<ResetPassword />} />
            <Route path="/club-onboarding" element={<ProtectedRoute><ClubOnboarding /></ProtectedRoute>} />
            <Route path="/event-onboarding" element={<ProtectedRoute><EventAdminOnboarding /></ProtectedRoute>} />
            <Route path="/claim-club/:clubId" element={<ProtectedRoute><ClaimClubForm /></ProtectedRoute>} />
            <Route path="/claim-organiser/:clubId" element={<ProtectedRoute><ClaimOrganiserForm /></ProtectedRoute>} />
            <Route path="/pending-approval" element={<ProtectedRoute><PendingApproval /></ProtectedRoute>} />
            <Route path="/" element={<ProtectedRoute><Layout /></ProtectedRoute>}>
              <Route index element={<Dashboard />} />
              <Route path="users" element={<ProtectedRoute requireSuperAdmin><Users /></ProtectedRoute>} />
              <Route path="organiser-requests" element={<ProtectedRoute allowedRoles={['SUPER_ADMIN', 'NORMAL_ADMIN']}><OrganiserRequests /></ProtectedRoute>} />
              <Route path="events" element={<ProtectedRoute allowedRoles={['SUPER_ADMIN', 'EVENT_ADMIN', 'NORMAL_ADMIN']}><Events /></ProtectedRoute>} />
              <Route path="clubs" element={<ProtectedRoute allowedRoles={['SUPER_ADMIN', 'CLUB_ADMIN', 'NORMAL_ADMIN']}><Clubs /></ProtectedRoute>} />
              <Route path="ticketing" element={<ProtectedRoute><Ticketing /></ProtectedRoute>} />
              <Route path="ads-broadcast" element={<ProtectedRoute requireSuperAdmin><AdsBroadcast /></ProtectedRoute>} />
              <Route path="polls-contests" element={<ProtectedRoute allowedRoles={['SUPER_ADMIN', 'NORMAL_ADMIN']}><PollsContests /></ProtectedRoute>} />
              <Route path="support-activity" element={<ProtectedRoute allowedRoles={['SUPER_ADMIN', 'NORMAL_ADMIN']}><SupportActivity /></ProtectedRoute>} />
              <Route path="contact-support" element={<ProtectedRoute allowedRoles={['CLUB_ADMIN', 'EVENT_ADMIN']}><ContactSupport /></ProtectedRoute>} />
              <Route path="activity-logs" element={<ProtectedRoute requireSuperAdmin><ActivityLogs /></ProtectedRoute>} />
              <Route path="analytics" element={<ProtectedRoute allowedRoles={['SUPER_ADMIN', 'EVENT_ADMIN', 'CLUB_ADMIN']}><Analytics /></ProtectedRoute>} />
              <Route path="settings" element={<ProtectedRoute allowedRoles={['SUPER_ADMIN', 'NORMAL_ADMIN', 'CITY_ADMIN']}><Settings /></ProtectedRoute>} />
              <Route path="manage-filters" element={<ProtectedRoute allowedRoles={['SUPER_ADMIN', 'NORMAL_ADMIN']}><ManageFilters /></ProtectedRoute>} />
              {/* Hidden for now, same reason as the sidebar link above —
                  redirects instead of rendering a page with no working backend. */}
              <Route path="recommendations" element={<ComingSoon title="Recommendations" description="AI-powered recommendations are coming soon. This feature will suggest events, clubs, and connections tailored to each user." />} />
              <Route path="admins" element={<ProtectedRoute requireSuperAdmin><Admins /></ProtectedRoute>} />
              <Route path="account-settings" element={<ProtectedRoute allowedRoles={['CLUB_ADMIN']}><AccountSettings /></ProtectedRoute>} />
              <Route path="bookings" element={<ProtectedRoute allowedRoles={['SUPER_ADMIN', 'CLUB_ADMIN']}><Bookings /></ProtectedRoute>} />
              <Route path="event-account-settings" element={<ProtectedRoute allowedRoles={['EVENT_ADMIN']}><EventAccountSettings /></ProtectedRoute>} />
              <Route path="event-profile" element={<ProtectedRoute allowedRoles={['EVENT_ADMIN']}><EventAdminProfilePage /></ProtectedRoute>} />
              <Route path="club-profile" element={<ProtectedRoute allowedRoles={['CLUB_ADMIN']}><ClubProfilePage /></ProtectedRoute>} />
            </Route>
            <Route path="*" element={<Navigate to="/" replace />} />
          </Routes>
        </BrowserRouter>
      </AuthProvider>
        </ToastProvider>
    </QueryClientProvider>
  );
}